/**
 * Public smoke test — the canonical alchemy live-test pattern.
 * DO NOT EDIT this file; add your own tests as sibling files in test/.
 *
 * `Test.make` + `beforeAll(deploy(Stack))` shares ONE deploy across the file;
 * `afterAll.skipIf(NO_DESTROY)` leaves the deployment alive when NO_DESTROY=1
 * (as it is during grading).
 */
import { expect } from "@effect/vitest";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Test from "alchemy/Test/Vitest";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as HttpClient from "effect/unstable/http/HttpClient";
import Stack from "../alchemy.run.ts";

const { test, beforeAll, afterAll, deploy, destroy } = Test.make({
  providers: Cloudflare.providers(),
  stage: process.env.STAGE ?? "test",
});

const stack = beforeAll(deploy(Stack));
afterAll.skipIf(!!process.env.NO_DESTROY)(destroy(Stack));

test(
  "health endpoint serves 200",
  Effect.gen(function* () {
    const { url } = yield* stack;
    const client = yield* HttpClient.HttpClient;
    const response = yield* client
      .get(`${url}/health`)
      .pipe(
        Effect.retry({
          schedule: Schedule.exponential("500 millis"),
          times: 10,
        }),
      );
    expect(response.status).toBe(200);
    const body = (yield* response.json) as { ok: boolean };
    expect(body.ok).toBe(true);
  }),
  { timeout: 180_000 },
);
